<?php

/**
 * Writes updates.xml from the manifest.
 *
 *   php build/update-xml.php
 *
 * The update server is what an installed site reads to learn a new version
 * exists, and it points at a release asset by name. A stale one either hides a
 * release or offers a download that 404s, and neither shows up in any test - so
 * it is generated from the manifest rather than edited, and CI fails a release
 * whose generated file does not match what is committed.
 */

declare(strict_types=1);

$root     = \dirname(__DIR__);
$manifest = $root . '/yepr_gen.xml';

$xml = simplexml_load_file($manifest);

if ($xml === false) {
    fwrite(STDERR, "Cannot read the manifest at {$manifest}.\n");
    exit(1);
}

$version = trim((string) $xml->version);
$library = trim((string) $xml->libraryname);
$name    = trim((string) $xml->name);

$download = \sprintf(
    'https://github.com/HermanPeeren/generator-core/releases/download/v%s/lib_%s-%s.zip',
    $version,
    $library,
    $version
);

$updates = <<<XML
<?xml version="1.0" encoding="utf-8"?>
<!--
	Generated by build/update-xml.php from yepr_gen.xml. Do not edit by hand:
	run the script and commit the result.
-->
<updates>
	<update>
		<name>{$name}</name>
		<description>Shared code for the Yepr generator extensions.</description>
		<element>{$library}</element>
		<type>library</type>
		<version>{$version}</version>
		<downloads>
			<downloadurl type="full" format="zip">{$download}</downloadurl>
		</downloads>
		<maintainer>Herman Peeren</maintainer>
		<maintainerurl>https://yepr.nl</maintainerurl>
		<targetplatform name="joomla" version="6\..*"/>
		<php_minimum>8.3</php_minimum>
	</update>
</updates>

XML;

file_put_contents($root . '/updates.xml', $updates);

echo "updates.xml written for {$library} {$version}\n";
